      : r.salary_from
        ? `от ${short(r.salary_from)}`
        : `до ${short(r.salary_to)}`;
  return `💰 ${range} ${CURRENCY[r.currency] ?? r.currency ?? ''}${r.salary_gross ? ' до налогов' : ''}`;
